select css.subject_abbreviation subject, tsu1.real_name real_name, td.dict_name sale_site, td1.dict_name oil_site, cc.customer_name customer_name, fcs.ship_name ship_name, fcosh.update_oil_num quantity, fcosh.update_oil_vice_num quantity_liter, fop.payoil_code plan_code, fg.goods_name goods_name, fcosh.reimbursement_time reimbursement_time, foc.create_time from ffp_cust_oil_stora_his fcosh left join ffp_order_payoil fop on fcosh.plan_code = fop.payoil_code left join cap_customer cc on cc.customer_id = fcosh.customer_id left join ffp_cust_ship fcs on fcs.ship_id = fop.ship_id left join ffp_goods fg on fcosh.goods_id = fg.goods_id left join ffp_goods_cate fgc on fg.goods_category_id = fgc.goods_category_id left join t_dict td on fcosh.stora_site_id = td.dict_id left join t_dict td1 on fop.oil_site_id = td1.dict_id left join cap_sale_subject css on fcosh.oil_channel_id = css.subject_id left join ffp_order_consign foc on fop.payoil_id = foc.order_id left join t_sys_user tsu1 on foc.consign_user_id = tsu1.user_id where left(fcosh.plan_code, 1) = 'B' and fcosh.stora_site_id != fop.oil_site_id and fcosh.update_oil_num != 0 and (fcosh.reimbursement_time is null or fcosh.reimbursement_time >= '2023-01-01 00:00:00') and DATE_FORMAT(foc.create_time, '%Y-%m-%d') >= '2026-04-27' and DATE_FORMAT(foc.create_time, '%Y-%m-%d') <= '2026-04-29' group by storage_id order by storage_id desc;
